// Validate & normalize a single claim submission.
// - Coerces estimatedLoss to a Number (handles "15000", "15,000", "$15,000")
// - Lowercases policyType for branch comparison
// - Trims & strips all string fields
// - Validates required fields (clientName, policyType, estimatedLoss, description, claimantEmail, claimDate)
// - Computes priorityStatus ("URGENT" | "STANDARD") and isUrgent flag
//   Urgent rule: estimatedLoss > 15000 OR policyType === "commercial"  (strictly > 15000)
// - On validation failure, sets _error=true and routes a structured
//   error object downstream (Webhook Response handles 400).

const REQUIRED = ['clientName', 'policyType', 'estimatedLoss', 'description', 'claimantEmail', 'claimDate'];
const URGENT_THRESHOLD = 15000;
const ALLOWED_POLICY_TYPES = ['private', 'commercial'];

function toNumber(v) {
  if (typeof v === 'number' && isFinite(v)) return v;
  if (typeof v !== 'string') return NaN;
  const cleaned = v.replace(/[$,\s]/g, '');
  if (cleaned === '' || /[^0-9.+-]/.test(cleaned)) return NaN;
  const n = Number(cleaned);
  return isFinite(n) ? n : NaN;
}

function trimStr(v) {
  return typeof v === 'string' ? v.trim() : (v == null ? '' : String(v).trim());
}

function isEmail(s) {
  return /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(s || '').trim());
}

function parseDate(raw) {
  if (!raw) return '';
  const d = new Date(raw);
  if (isNaN(d.getTime())) return '';
  return d.toISOString();
}

const items = $input.all();
const out = [];

for (const it of items) {
  // Webhook payload may be at j.body (form-encoded) OR top-level JSON
  const j = it.json || {};
  const src = (j.body && typeof j.body === 'object') ? j.body : j;

  const clientName = trimStr(src.clientName ?? src.client_name ?? src.ClientName);
  const policyTypeRaw = trimStr(src.policyType ?? src.policy_type ?? src.PolicyType);
  const policyType = policyTypeRaw.toLowerCase();
  const estimatedLossRaw = src.estimatedLoss ?? src.estimated_loss ?? src.EstimatedLoss;
  const estimatedLoss = toNumber(estimatedLossRaw);
  const description = trimStr(src.description ?? src.Description);
  const claimantEmail = trimStr(src.claimantEmail ?? src.claimant_email ?? src.ClaimantEmail).toLowerCase();
  const claimDateRaw = src.claimDate ?? src.claim_date ?? src.ClaimDate;
  const claimDate = parseDate(claimDateRaw);

  const errors = [];
  if (!clientName) errors.push('clientName is required');
  if (!policyTypeRaw) errors.push('policyType is required');
  else if (!ALLOWED_POLICY_TYPES.includes(policyType)) errors.push(`policyType must be one of: ${ALLOWED_POLICY_TYPES.join(', ')}`);
  if (!isFinite(estimatedLoss)) errors.push('estimatedLoss must be a number');
  if (!description) errors.push('description is required');
  if (!claimantEmail) errors.push('claimantEmail is required');
  else if (!isEmail(claimantEmail)) errors.push('claimantEmail must be a valid email');
  if (!claimDateRaw) errors.push('claimDate is required');
  else if (!claimDate) errors.push('claimDate must be a parseable date');

  const isUrgent = errors.length === 0 && (estimatedLoss > URGENT_THRESHOLD || policyType === 'commercial');
  const priorityStatus = isUrgent ? 'URGENT' : 'STANDARD';

  out.push({
    json: {
      clientName,
      policyType,
      policyTypeRaw,
      estimatedLoss: isFinite(estimatedLoss) ? estimatedLoss : 0,
      estimatedLossRaw: estimatedLossRaw == null ? '' : String(estimatedLossRaw),
      description,
      claimantEmail,
      claimDate: claimDate || '',
      submittedAt: new Date().toISOString(),
      isUrgent,
      priorityStatus,
      _error: errors.length > 0,
      _errors: errors,
      _reason: errors.length > 0 ? errors.join('; ') : ''
    }
  });
}

return out;

// Merge OpenRouter classification onto the validated claim record.
// If OpenRouter failed (continueOnFail=true upstream) OR returned
// malformed JSON, fall back to a deterministic category + summary so
// the workflow always produces a Slack alert + Airtable record.

const CATEGORIES = ['collision', 'storm_damage', 'theft', 'fire', 'mechanical', 'liability', 'other'];

function guessCategory(description) {
  const s = String(description || '').toLowerCase();
  if (/(collision|collid|crash|struck|impact|rear-end|rear end|hit )/.test(s)) return 'collision';
  if (/(storm|hurricane|wind|wave|swell|surge|flood|lightning|hail|tropical)/.test(s)) return 'storm_damage';
  if (/(theft|stolen|burglar|break.?in|robbery|robbed)/.test(s)) return 'theft';
  if (/(fire|burn|smoke|combust|engine room fire)/.test(s)) return 'fire';
  if (/(engine|mechanical|propeller|gearbox|transmission|electrical fail|hydraulic|leak |oil leak|pump fail)/.test(s)) return 'mechanical';
  if (/(injur|liability|third.?party|passenger|crew member|bodily harm|negligence)/.test(s)) return 'liability';
  return 'other';
}

function summarize(claim, category) {
  const lossStr = '$' + Number(claim.estimatedLoss || 0).toLocaleString('en-US');
  const cat = String(category || 'other').replace('_', ' ');
  const desc = String(claim.description || '').replace(/\s+/g, ' ').trim();
  const snippet = desc.length > 100 ? desc.slice(0, 97) + '...' : desc;
  return `${claim.policyType === 'commercial' ? 'Commercial' : 'Private'} ${cat} claim from ${claim.clientName} (${lossStr}): ${snippet}`.slice(0, 240);
}

const ai = $input.first().json;
const claim = $('Code - Validate & Normalize').item.json;

let category = '';
let summary = '';
let aiUsed = false;
let aiError = '';

try {
  const raw = ai && ai.choices && ai.choices[0] && ai.choices[0].message && ai.choices[0].message.content;
  if (raw) {
    let parsed;
    try { parsed = JSON.parse(raw); } catch (e) {
      const m = String(raw).match(/\{[\s\S]*\}/);
      if (m) parsed = JSON.parse(m[0]);
    }
    if (parsed && typeof parsed === 'object') {
      const c = String(parsed.category || '').toLowerCase().trim().replace(/\s+/g, '_');
      if (CATEGORIES.includes(c)) category = c;
      if (typeof parsed.summary === 'string' && parsed.summary.trim().length >= 10) summary = parsed.summary.trim();
    }
    if (category && summary) aiUsed = true;
  }
  if (ai && ai.error) aiError = String(ai.error.message || ai.error);
} catch (e) {
  aiError = String(e && e.message || e);
}

if (!category) category = guessCategory(claim.description);
if (!summary) summary = summarize(claim, category);

return [{
  json: {
    ...claim,
    category,
    summary,
    aiUsed,
    aiError
  }
}];

